-- 1. List all rooms and their types.
CREATE VIEW room_catalog AS
SELECT room_id, room_number, room_type, price_per_night, is_available
FROM Rooms;

-- 2. Bookings of one guest (cancelled ones excluded).
CREATE FUNCTION guest_bookings(p_guest_id INT)
RETURNS TABLE (booking_id INT, room_number VARCHAR, check_in_date DATE,
               check_out_date DATE, total_cost DECIMAL) AS $$
    SELECT b.booking_id, r.room_number, b.check_in_date, b.check_out_date, b.total_cost
    FROM Bookings b JOIN Rooms r ON r.room_id = b.room_id
    WHERE b.guest_id = p_guest_id AND b.is_cancelled = FALSE
    ORDER BY b.check_in_date;
$$ LANGUAGE sql;

-- 3. Total cost of all (still valid) bookings.
CREATE FUNCTION total_revenue() RETURNS DECIMAL AS $$
    SELECT COALESCE(SUM(total_cost), 0) FROM Bookings WHERE is_cancelled = FALSE;
$$ LANGUAGE sql;

-- 4. Make a new booking; returns NULL when the request cannot be honoured.
CREATE FUNCTION book_room(p_room_id INT, p_guest_id INT,
                          p_check_in DATE, p_check_out DATE) RETURNS INT AS $$
DECLARE
    v_price   DECIMAL(10,2);
    v_booking INT;
BEGIN
    IF p_check_out <= p_check_in THEN
        RETURN NULL;
    END IF;
    SELECT price_per_night INTO v_price
    FROM Rooms WHERE room_id = p_room_id AND is_available = TRUE;
    IF v_price IS NULL THEN
        RETURN NULL;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM Guests WHERE guest_id = p_guest_id AND is_active = TRUE) THEN
        RETURN NULL;
    END IF;
    IF EXISTS (SELECT 1 FROM Bookings
               WHERE room_id = p_room_id AND is_cancelled = FALSE
                 AND p_check_in < check_out_date AND p_check_out > check_in_date) THEN
        RETURN NULL;
    END IF;
    INSERT INTO Bookings (room_id, guest_id, check_in_date, check_out_date, total_cost, is_cancelled)
    VALUES (p_room_id, p_guest_id, p_check_in, p_check_out,
            (p_check_out - p_check_in) * v_price, FALSE)
    RETURNING booking_id INTO v_booking;
    UPDATE Rooms SET is_available = FALSE WHERE room_id = p_room_id;
    RETURN v_booking;
END;
$$ LANGUAGE plpgsql;

-- 5. Extend (or shorten) a stay and reprice it.
CREATE FUNCTION update_checkout(p_booking_id INT, p_new_checkout DATE) RETURNS BOOLEAN AS $$
DECLARE
    v_rows INT;
BEGIN
    UPDATE Bookings b
    SET check_out_date = p_new_checkout,
        total_cost = (p_new_checkout - b.check_in_date) * r.price_per_night
    FROM Rooms r
    WHERE r.room_id = b.room_id
      AND b.booking_id = p_booking_id
      AND b.is_cancelled = FALSE
      AND p_new_checkout > b.check_in_date;
    GET DIAGNOSTICS v_rows = ROW_COUNT;
    IF v_rows = 0 THEN
        RETURN FALSE;
    END IF;
    RETURN TRUE;
END;
$$ LANGUAGE plpgsql;

