SELECT book_room(2, 8, '2026-03-05', '2026-03-08') AS inactive_guest_booking;
SELECT update_checkout(1, '2026-01-15') AS stay_extended;
SELECT * FROM guest_bookings(7);
SELECT total_revenue() AS revenue;

