-- Subscription tracking module (PostgreSQL)

-- Subscriptions carry a renewal flag alongside the schema columns.
ALTER TABLE Subscriptions ADD COLUMN auto_renew BOOLEAN NOT NULL DEFAULT true;

-- 5. Cancel a subscription; reports whether a row was actually cancelled.
CREATE FUNCTION cancel_subscription(p_subscription_id INT)
RETURNS BOOLEAN AS $$
BEGIN
    UPDATE Subscriptions
    SET status = 'Cancelled',
        auto_renew = false
    WHERE subscription_id = p_subscription_id
      AND status <> 'Cancelled';

    IF NOT FOUND THEN
        RETURN false;
    END IF;
    RETURN true;
END;
$$ LANGUAGE plpgsql;

-- 4. Create a new subscription for a user.
CREATE FUNCTION create_subscription(p_user_id INT, p_plan_id INT, p_start DATE,
                                    p_end DATE, p_auto_renew BOOLEAN)
RETURNS INT AS $$
DECLARE
    v_subscription_id INT;
BEGIN
    IF NOT EXISTS (SELECT 1 FROM Users WHERE user_id = p_user_id) THEN
        RAISE EXCEPTION 'unknown user %', p_user_id;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM Plans WHERE plan_id = p_plan_id) THEN
        RAISE EXCEPTION 'unknown plan %', p_plan_id;
    END IF;

    INSERT INTO Subscriptions (subscription_id, user_id, plan_id, start_date,
                               end_date, status, auto_renew)
    SELECT COALESCE(MAX(subscription_id), 0) + 1, p_user_id, p_plan_id, p_start,
           p_end, 'Active', p_auto_renew
    FROM Subscriptions
    RETURNING subscription_id INTO v_subscription_id;

    RETURN v_subscription_id;
END;
$$ LANGUAGE plpgsql;

-- 1. All users together with their active subscriptions.
CREATE VIEW v_user_active_subscriptions AS
SELECT u.user_id, u.username, u.email, p.plan_name, p.price_monthly,
       s.start_date, s.end_date, s.auto_renew
FROM Users u
LEFT JOIN Subscriptions s ON s.user_id = u.user_id AND s.status = 'Active'
LEFT JOIN Plans p         ON p.plan_id = s.plan_id;

-- 3. Number of subscriptions per plan, with the renewing share.
CREATE VIEW v_subscriptions_per_plan AS
SELECT p.plan_id,
       p.plan_name,
       COUNT(s.subscription_id)                                    AS total_subscriptions,
       COUNT(s.subscription_id) FILTER (WHERE s.auto_renew = true) AS renewing_subscriptions
FROM Plans p
LEFT JOIN Subscriptions s ON s.plan_id = p.plan_id
GROUP BY p.plan_id, p.plan_name;

-- 2. Users subscribed to a given plan.
CREATE FUNCTION users_on_plan(p_plan_name VARCHAR)
RETURNS TABLE (user_id INT, username VARCHAR, email VARCHAR, status VARCHAR) AS $$
    SELECT u.user_id, u.username, u.email, s.status
    FROM Users u
    JOIN Subscriptions s ON s.user_id = u.user_id
    JOIN Plans p         ON p.plan_id = s.plan_id
    WHERE p.plan_name = p_plan_name
    ORDER BY u.username;
$$ LANGUAGE sql;

