    (1, 'alice', 'alice@example.com'),
    (2, 'bob',   'bob@example.com'),
    (3, 'carol', 'carol@example.com');

INSERT INTO Plans (plan_id, plan_name, price_monthly, features) VALUES
    (1, 'Basic Plan',   9.99,  'core features'),
    (2, 'Premium Plan', 29.99, 'core + priority support');

SELECT create_subscription(1, 2, DATE '2026-01-01', DATE '2026-12-31', true);
SELECT create_subscription(2, 2, DATE '2026-02-01', DATE '2026-08-01', false);
SELECT create_subscription(3, 1, DATE '2026-03-01', NULL, true);

SELECT * FROM v_user_active_subscriptions;
SELECT * FROM users_on_plan('Premium Plan');
SELECT * FROM v_subscriptions_per_plan ORDER BY total_subscriptions DESC;
SELECT cancel_subscription(2);
SELECT username, plan_name, end_date
FROM v_user_active_subscriptions
WHERE auto_renew = false;

