CREATE TABLE Campaigns (
    campaign_id   INT PRIMARY KEY,
    campaign_name VARCHAR(100) NOT NULL,
    start_date    DATE NOT NULL,
    end_date      DATE NOT NULL,
    budget        DECIMAL(12,2) NOT NULL,
    is_active     BOOLEAN NOT NULL DEFAULT true
);

CREATE TABLE Channels (
    channel_id   INT PRIMARY KEY,
    channel_name VARCHAR(100) NOT NULL,
    channel_type VARCHAR(50)  NOT NULL,
    is_enabled   BOOLEAN NOT NULL DEFAULT true
);

CREATE TABLE Performance (
    performance_id INT PRIMARY KEY,
    campaign_id    INT NOT NULL REFERENCES Campaigns(campaign_id),
    channel_id     INT NOT NULL REFERENCES Channels(channel_id),
    date           DATE NOT NULL,
    impressions    INT NOT NULL,
    clicks         INT NOT NULL,
    conversions    INT NOT NULL,
    is_validated   BOOLEAN NOT NULL DEFAULT false
);

CREATE FUNCTION fn_campaign_performance()
RETURNS TABLE (campaign_name VARCHAR, channel_name VARCHAR, date DATE,
               impressions INT, clicks INT, conversions INT) AS $$
    SELECT c.campaign_name, ch.channel_name, p.date, p.impressions, p.clicks, p.conversions
    FROM Campaigns c
    LEFT JOIN Performance p ON p.campaign_id = c.campaign_id AND p.is_validated = true
    LEFT JOIN Channels ch ON ch.channel_id = p.channel_id
    ORDER BY c.campaign_name, p.date;
$$ LANGUAGE sql;

CREATE FUNCTION fn_performance_for_campaign(p_name VARCHAR)
RETURNS TABLE (channel_name VARCHAR, date DATE, impressions INT, clicks INT, conversions INT) AS $$
    SELECT ch.channel_name, p.date, p.impressions, p.clicks, p.conversions
    FROM Performance p
    JOIN Campaigns c ON c.campaign_id = p.campaign_id
    JOIN Channels ch ON ch.channel_id = p.channel_id
    WHERE c.campaign_name = p_name
      AND p.is_validated = true
    ORDER BY p.date;
$$ LANGUAGE sql;

CREATE FUNCTION fn_clicks_by_channel_type()
RETURNS TABLE (channel_type VARCHAR, total_clicks BIGINT) AS $$
    SELECT ch.channel_type, SUM(p.clicks)
    FROM Channels ch
    JOIN Performance p ON p.channel_id = ch.channel_id
    WHERE ch.is_enabled = true
      AND p.is_validated = true
    GROUP BY ch.channel_type
    ORDER BY 2 DESC;
$$ LANGUAGE sql;

CREATE FUNCTION fn_add_campaign(p_name VARCHAR, p_start DATE, p_end DATE, p_budget DECIMAL)
RETURNS INT AS $$
DECLARE v_id INT;
BEGIN
    IF p_end < p_start OR p_budget <= 0 THEN
        RAISE EXCEPTION 'invalid campaign window or budget for %', p_name;
    END IF;
    SELECT COALESCE(MAX(campaign_id), 0) + 1 INTO v_id FROM Campaigns;
    INSERT INTO Campaigns (campaign_id, campaign_name, start_date, end_date, budget, is_active)
    VALUES (v_id, p_name, p_start, p_end, p_budget, p_end >= CURRENT_DATE);
    RETURN v_id;
END;
$$ LANGUAGE plpgsql;

CREATE FUNCTION fn_record_performance(p_campaign INT, p_channel INT, p_date DATE,
                                      p_impr INT, p_clicks INT, p_conv INT)
RETURNS INT AS $$
DECLARE v_id INT;
BEGIN
    IF NOT EXISTS (SELECT 1 FROM Channels WHERE channel_id = p_channel AND is_enabled = true) THEN
        RAISE EXCEPTION 'channel % is not enabled', p_channel;
    END IF;
    IF p_clicks > p_impr OR p_conv > p_clicks THEN
        RAISE EXCEPTION 'inconsistent funnel numbers';
    END IF;
    SELECT COALESCE(MAX(performance_id), 0) + 1 INTO v_id FROM Performance;
    INSERT INTO Performance (performance_id, campaign_id, channel_id, date,
                             impressions, clicks, conversions, is_validated)
    VALUES (v_id, p_campaign, p_channel, p_date, p_impr, p_clicks, p_conv, false);
    RETURN v_id;
END;
$$ LANGUAGE plpgsql;

CREATE FUNCTION fn_validate_campaign_rows(p_campaign INT)
RETURNS INT AS $$
DECLARE v_count INT;
BEGIN
    UPDATE Performance
    SET is_validated = true
    WHERE campaign_id = p_campaign
      AND is_validated = false
      AND date <= CURRENT_DATE;
    GET DIAGNOSTICS v_count = ROW_COUNT;
    RETURN v_count;
END;
$$ LANGUAGE plpgsql;

INSERT INTO Channels (channel_id, channel_name, channel_type, is_enabled) VALUES
    (1, 'Google Search', 'Search', true),
    (2, 'Facebook Feed', 'Social', true),
    (3, 'Legacy Banner Net', 'Display', false);

SELECT fn_add_campaign('Summer Sale', DATE '2024-06-01', DATE '2024-08-31', 50000.00);
SELECT fn_add_campaign('Winter Teaser', DATE '2024-11-01', DATE '2024-12-24', 18000.00);

SELECT fn_record_performance(1, 1, DATE '2024-06-05', 120000, 4800, 260);
SELECT fn_record_performance(1, 2, DATE '2024-06-05', 90000, 2700, 140);
SELECT fn_record_performance(2, 1, DATE '2024-11-04', 40000, 1500, 95);

SELECT fn_validate_campaign_rows(1);
SELECT fn_validate_campaign_rows(2);

SELECT * FROM fn_campaign_performance();
SELECT * FROM fn_performance_for_campaign('Summer Sale');
SELECT * FROM fn_clicks_by_channel_type();
SELECT campaign_name, budget FROM Campaigns WHERE is_active = true ORDER BY start_date;

