CREATE TABLE Customers (
    CustomerID INT PRIMARY KEY,
    Name VARCHAR(50),
    Email VARCHAR(100)
);

CREATE TABLE Orders (
    OrderID INT PRIMARY KEY,
    CustomerID INT,
    OrderDate DATE,
    TotalAmount DECIMAL(10,2),
    IsShipped BOOLEAN
);

CREATE TABLE OrderItems (
    OrderItemID INT PRIMARY KEY,
    OrderID INT,
    Product VARCHAR(100),
    Quantity INT,
    PricePerUnit DECIMAL(10,2),
    IsReturned BOOLEAN
);

INSERT INTO Customers (CustomerID, Name, Email) VALUES
(1, 'Alice Smith', 'alice@example.com'),
(2, 'Bob Johnson', 'bob@example.com');

INSERT INTO Orders (OrderID, CustomerID, OrderDate, TotalAmount, IsShipped) VALUES
(101, 1, CURRENT_DATE - INTERVAL '15 days', 150.00, true),
(102, 2, CURRENT_DATE - INTERVAL '45 days', 200.00, false),
(103, 1, CURRENT_DATE - INTERVAL '5 days', 75.00, true);

INSERT INTO OrderItems (OrderItemID, OrderID, Product, Quantity, PricePerUnit, IsReturned) VALUES
(1, 101, 'Laptop', 1, 1200.00, false),
(2, 101, 'Mouse', 1, 30.00, false),
(3, 102, 'Keyboard', 1, 75.00, false),
(4, 103, 'Monitor', 1, 150.00, true),
(5, 103, 'Webcam', 1, 50.00, false);

-- Query 1: Select customers who placed an order in the last month
SELECT DISTINCT c.Name, c.Email FROM Customers c JOIN Orders o ON c.CustomerID = o.CustomerID WHERE o.OrderDate >= CURRENT_DATE - INTERVAL '1 month' AND o.IsShipped = true;

-- Query 2: Calculate total revenue for each customer
SELECT c.Name, SUM(o.TotalAmount) AS TotalRevenue FROM Customers c JOIN Orders o ON c.CustomerID = o.CustomerID GROUP BY c.Name;

-- Query 3: Find the top 5 most ordered products
SELECT Product, SUM(Quantity) AS TotalQuantityOrdered FROM OrderItems WHERE IsReturned = false GROUP BY Product ORDER BY TotalQuantityOrdered DESC LIMIT 5;

