INSERT INTO Participants (ParticipantID, FirstName, LastName, DateOfBirth, Gender, ConsentGiven)
VALUES (10, 'Ana', 'Ferreira', DATE '1988-06-02', 'Female', true),
       (11, 'Boris', 'Katz', DATE '1975-11-20', 'Male', true),
       (12, 'Chen', 'Liu', DATE '1992-02-09', 'Other', false);

SELECT enroll_participant(1, 10, DATE '2024-02-01') AS ana_trial_x;
SELECT enroll_participant(1, 11, DATE '2024-02-05') AS boris_trial_x;
SELECT enroll_participant(2, 11, DATE '2024-03-10') AS boris_trial_y;
SELECT enroll_participant(3, 10, DATE '2024-02-06') AS ana_closed_trial;
