    (1, 'Deployment Runbook', false),
    (2, 'Legacy Pricing Sheet', true);

select add_version(1, 'Step 1: pull the image.', 'ana');
select add_version(1, 'Step 1: pull the image. Step 2: migrate.', 'bo');
select get_latest_content(1) as latest_content;
select * from get_document_versions(1);
select * from documents_by_author('ana');
select * from version_counts();

