CREATE FUNCTION active_polls()
RETURNS TABLE (poll_id INTEGER, poll_question TEXT, created_by_user_id INTEGER) AS $$
    SELECT p.poll_id, p.poll_question, p.created_by_user_id
    FROM Polls p
    WHERE p.is_active = TRUE
    ORDER BY p.created_at;
$$ LANGUAGE sql STABLE;

CREATE FUNCTION votes_per_user()
RETURNS TABLE (voter_user_id INTEGER, total_votes BIGINT) AS $$
    SELECT v.voter_user_id, count(*)
    FROM Votes v
    GROUP BY v.voter_user_id
    ORDER BY count(*) DESC, v.voter_user_id;
$$ LANGUAGE sql STABLE;

