CREATE TABLE Users (
    user_id   SERIAL PRIMARY KEY,
    username  TEXT NOT NULL UNIQUE,
    is_active BOOLEAN NOT NULL DEFAULT true
);

CREATE TABLE Products (
    product_id   SERIAL PRIMARY KEY,
    product_name TEXT NOT NULL,
    price        NUMERIC(10,2) NOT NULL,
    in_stock     BOOLEAN NOT NULL DEFAULT true
);

CREATE TABLE Wishlists (
    wishlist_id    SERIAL PRIMARY KEY,
    user_id        INTEGER NOT NULL REFERENCES Users(user_id),
    product_id     INTEGER NOT NULL REFERENCES Products(product_id),
    added_date     DATE NOT NULL DEFAULT CURRENT_DATE,
    quantity       INTEGER NOT NULL DEFAULT 1,
    notify_on_sale BOOLEAN NOT NULL DEFAULT false,
    UNIQUE (user_id, product_id)
);

INSERT INTO Users (username, is_active) VALUES
    ('ana', true),
    ('bruno', true),
    ('carla', false);

INSERT INTO Products (product_name, price, in_stock) VALUES
    ('Mechanical Keyboard', 129.90, true),
    ('Noise Cancelling Headphones', 249.00, true),
    ('Vintage Desk Lamp', 59.50, false);

-- 1. List all products in a specific user's wishlist.
CREATE FUNCTION get_user_wishlist(p_user_id INTEGER)
RETURNS TABLE (product_id INTEGER, product_name TEXT, price NUMERIC, quantity INTEGER, added_date DATE)
LANGUAGE sql AS $$
    SELECT p.product_id, p.product_name, p.price, w.quantity, w.added_date
    FROM Wishlists w
    JOIN Products p ON p.product_id = w.product_id
    WHERE w.user_id = p_user_id
    ORDER BY w.added_date, p.product_name;
$$;

-- 2. Find all users who have a particular product in their wishlist.
CREATE FUNCTION find_users_with_product(p_product_id INTEGER)
RETURNS TABLE (user_id INTEGER, username TEXT, wants_alert BOOLEAN)
LANGUAGE sql AS $$
    SELECT u.user_id, u.username, w.notify_on_sale
    FROM Wishlists w
    JOIN Users u ON u.user_id = w.user_id
    WHERE w.product_id = p_product_id
      AND u.is_active = true
    ORDER BY u.username;
$$;

-- 3. Add a product to a user's wishlist (idempotent: bumps quantity instead of duplicating).
CREATE FUNCTION add_to_wishlist(p_user_id INTEGER, p_product_id INTEGER, p_quantity INTEGER, p_notify BOOLEAN)
RETURNS INTEGER
LANGUAGE plpgsql AS $$
DECLARE
    v_id INTEGER;
BEGIN
    IF NOT EXISTS (SELECT 1 FROM Users WHERE user_id = p_user_id AND is_active = true) THEN
        RAISE EXCEPTION 'user % is not an active account', p_user_id;
    END IF;
    INSERT INTO Wishlists (user_id, product_id, quantity, notify_on_sale)
    VALUES (p_user_id, p_product_id, p_quantity, p_notify)
    ON CONFLICT (user_id, product_id) DO UPDATE
        SET quantity = Wishlists.quantity + EXCLUDED.quantity,
            notify_on_sale = Wishlists.notify_on_sale OR EXCLUDED.notify_on_sale
    RETURNING wishlist_id INTO v_id;
    RETURN v_id;
END;
$$;

-- 4. Remove a product from a user's wishlist; reports whether a row was deleted.
CREATE FUNCTION remove_from_wishlist(p_user_id INTEGER, p_product_id INTEGER)
RETURNS BOOLEAN
LANGUAGE plpgsql AS $$
DECLARE
    v_removed INTEGER;
BEGIN
    DELETE FROM Wishlists
    WHERE user_id = p_user_id
      AND product_id = p_product_id;
    GET DIAGNOSTICS v_removed = ROW_COUNT;
    IF v_removed = 0 THEN
        RETURN false;
    END IF;
    RETURN true;
END;
$$;

-- 5. Total number of wishlisted products across all users.
CREATE FUNCTION total_wishlist_products(p_only_available BOOLEAN)
RETURNS BIGINT
LANGUAGE sql AS $$
    SELECT COALESCE(SUM(w.quantity), 0)
    FROM Wishlists w
    JOIN Products p ON p.product_id = w.product_id
    WHERE p_only_available = false
       OR p.in_stock = true;
$$;

SELECT add_to_wishlist(1, 1, 1, true);
SELECT add_to_wishlist(1, 3, 2, false);
SELECT add_to_wishlist(2, 1, 1, true);
SELECT * FROM get_user_wishlist(1);
SELECT * FROM find_users_with_product(1);
SELECT remove_from_wishlist(1, 3) AS removed_lamp;
SELECT remove_from_wishlist(2, 3) AS removed_missing_row;
SELECT total_wishlist_products(false) AS all_items,
       total_wishlist_products(true)  AS in_stock_items;

