CREATE TABLE Alumni (
    alumnus_id      SERIAL PRIMARY KEY,
    alumnus_name    TEXT NOT NULL,
    graduation_year INT  NOT NULL,
    email           TEXT NOT NULL
);

CREATE TABLE Funds (
    fund_id       SERIAL PRIMARY KEY,
    fund_name     TEXT NOT NULL,
    description   TEXT,
    accepts_gifts BOOLEAN NOT NULL DEFAULT true
);

CREATE TABLE Donations (
    donation_id   SERIAL PRIMARY KEY,
    alumnus_id    INT NOT NULL REFERENCES Alumni(alumnus_id),
    fund_id       INT NOT NULL REFERENCES Funds(fund_id),
    amount        NUMERIC(12,2) NOT NULL CHECK (amount > 0),
    donation_date DATE NOT NULL,
    is_anonymous  BOOLEAN NOT NULL,
    is_refunded   BOOLEAN NOT NULL DEFAULT false
);

INSERT INTO Alumni (alumnus_name, graduation_year, email) VALUES
    ('Ada Ng',      2004, 'ada@example.org'),
    ('Ben Harlow',  2004, 'ben@example.org'),
    ('Cora Diaz',   2011, 'cora@example.org');

INSERT INTO Funds (fund_name, description, accepts_gifts) VALUES
    ('Library Endowment',  'Books and archives',      true),
    ('Chapel Restoration', 'Closed after completion', false);

-- 3. Record a new donation to a fund by an alumnus.
CREATE FUNCTION record_donation(p_alumnus_id INT, p_fund_id INT, p_amount NUMERIC,
                                p_date DATE, p_anonymous BOOLEAN)
RETURNS INT AS $$
DECLARE v_id INT;
BEGIN
    PERFORM 1 FROM Funds WHERE fund_id = p_fund_id AND accepts_gifts = true;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Fund % is not accepting gifts', p_fund_id;
    END IF;
    INSERT INTO Donations (alumnus_id, fund_id, amount, donation_date, is_anonymous, is_refunded)
    VALUES (p_alumnus_id, p_fund_id, p_amount, p_date, p_anonymous, false)
    RETURNING donation_id INTO v_id;
    RETURN v_id;
END;
$$ LANGUAGE plpgsql;

-- 1. Total donations to a specific fund.
CREATE FUNCTION fund_total(p_fund_id INT) RETURNS NUMERIC AS $$
    SELECT COALESCE(SUM(amount), 0)
    FROM Donations
    WHERE fund_id = p_fund_id AND is_refunded = false;
$$ LANGUAGE sql;

-- 2. All donations made by a particular alumnus.
CREATE FUNCTION alumnus_donations(p_alumnus_id INT)
RETURNS TABLE (donation_id INT, fund_name TEXT, amount NUMERIC,
               donation_date DATE, is_anonymous BOOLEAN) AS $$
    SELECT d.donation_id, f.fund_name, d.amount, d.donation_date, d.is_anonymous
    FROM Donations d
    JOIN Funds f ON f.fund_id = d.fund_id
    WHERE d.alumnus_id = p_alumnus_id AND d.is_refunded = false
    ORDER BY d.donation_date;
$$ LANGUAGE sql;

-- 4. Alumni from a specific graduation year who have donated.
CREATE FUNCTION donors_from_year(p_year INT)
RETURNS TABLE (alumnus_id INT, alumnus_name TEXT, email TEXT) AS $$
    SELECT a.alumnus_id, a.alumnus_name, a.email
    FROM Alumni a
    WHERE a.graduation_year = p_year
      AND EXISTS (SELECT 1 FROM Donations d
                  WHERE d.alumnus_id = a.alumnus_id AND d.is_refunded = false);
$$ LANGUAGE sql;

-- 5. Total donation amount from each alumnus.
CREATE VIEW alumnus_giving AS
    SELECT a.alumnus_id, a.alumnus_name, COALESCE(SUM(d.amount), 0) AS total_given
    FROM Alumni a
    LEFT JOIN Donations d ON d.alumnus_id = a.alumnus_id AND d.is_refunded = false
    GROUP BY a.alumnus_id, a.alumnus_name
    ORDER BY total_given DESC;

SELECT record_donation(1, 1, 500.00, DATE '2023-05-01', false);
SELECT record_donation(2, 1, 125.50, DATE '2023-06-12', true);
SELECT record_donation(3, 1,  75.00, DATE '2024-01-09', false);
UPDATE Donations SET is_refunded = true WHERE donation_id = 3;

SELECT fund_total(1) AS library_total;
SELECT * FROM alumnus_donations(1);
SELECT * FROM donors_from_year(2004);
SELECT * FROM alumnus_giving;

