ALTER TABLE Employees ADD COLUMN department_id INT;
ALTER TABLE Employees ADD COLUMN is_active BOOLEAN NOT NULL DEFAULT true;
ALTER TABLE Departments ADD COLUMN is_active BOOLEAN NOT NULL DEFAULT true;
ALTER TABLE Salaries ADD COLUMN is_bonus BOOLEAN NOT NULL DEFAULT false;

-- 1. All employees of one department (only staff still on the payroll).
CREATE FUNCTION employees_in_department(p_department_id INT)
RETURNS TABLE (employee_id INT, name VARCHAR, position VARCHAR, salary DECIMAL) AS $$
    SELECT e.employee_id, e.name, e.position, e.salary
    FROM Employees e
    JOIN Departments d ON d.department_id = e.department_id
    WHERE e.department_id = p_department_id
      AND e.is_active = true
      AND d.is_active = true
    ORDER BY e.name;
$$ LANGUAGE sql;

-- 2. Average base salary per department.
CREATE VIEW department_average_salary AS
    SELECT d.department_id, d.name AS department_name, d.location,
           ROUND(AVG(e.salary), 2) AS average_salary,
           COUNT(*) AS headcount
    FROM Departments d
    JOIN Employees e ON e.department_id = d.department_id
    WHERE e.is_active = true
      AND d.is_active = true
    GROUP BY d.department_id, d.name, d.location;

-- 3. Record a salary payment; bonus payments are flagged separately.
CREATE FUNCTION record_salary_payment(p_employee_id INT, p_amount DECIMAL,
                                      p_pay_date TIMESTAMP, p_is_bonus BOOLEAN)
RETURNS INT AS $$
DECLARE v_salary_id INT;
BEGIN
    IF NOT EXISTS (SELECT 1 FROM Employees
                   WHERE employee_id = p_employee_id AND is_active = true) THEN
        RAISE EXCEPTION 'employee % is not on the active payroll', p_employee_id;
    END IF;
    IF p_amount <= 0 THEN
        RAISE EXCEPTION 'payment amount must be positive';
    END IF;
    SELECT COALESCE(MAX(salary_id), 0) + 1 INTO v_salary_id FROM Salaries;
    INSERT INTO Salaries (salary_id, employee_id, amount, pay_date, is_bonus)
    VALUES (v_salary_id, p_employee_id, p_amount, p_pay_date, p_is_bonus);
    RETURN v_salary_id;
END;
$$ LANGUAGE plpgsql;

-- 4. Promote / move an employee to another position.
CREATE FUNCTION update_employee_position(p_employee_id INT, p_position VARCHAR)
RETURNS BOOLEAN AS $$
DECLARE v_rows INT;
BEGIN
    UPDATE Employees SET position = p_position
    WHERE employee_id = p_employee_id
      AND is_active = true
      AND position <> p_position;
    GET DIAGNOSTICS v_rows = ROW_COUNT;
    IF v_rows = 0 THEN
        RETURN false;
    END IF;
    RETURN true;
END;
$$ LANGUAGE plpgsql;

-- 5. Departments whose regular monthly payroll exceeds $100,000.
CREATE FUNCTION departments_over_budget(p_month DATE)
RETURNS TABLE (department_name VARCHAR, location VARCHAR, monthly_total DECIMAL) AS $$
    SELECT d.name, d.location, SUM(s.amount) AS monthly_total
    FROM Departments d
    JOIN Employees e ON e.department_id = d.department_id
    JOIN Salaries s ON s.employee_id = e.employee_id
    WHERE s.is_bonus = false
      AND e.is_active = true
      AND s.pay_date >= p_month
      AND s.pay_date < p_month + INTERVAL '1 month'
    GROUP BY d.name, d.location
    HAVING SUM(s.amount) > 100000
    ORDER BY monthly_total DESC;
$$ LANGUAGE sql;

SELECT * FROM employees_in_department(3);
SELECT * FROM department_average_salary WHERE headcount > 1;
SELECT record_salary_payment(42, 5200.00, TIMESTAMP '2026-09-30 00:00:00', false);
SELECT record_salary_payment(42, 1500.00, TIMESTAMP '2026-09-30 00:00:00', true);
SELECT update_employee_position(42, 'Senior Analyst');
SELECT * FROM departments_over_budget(DATE '2026-09-01');

