    (2, 'Nina Vex', 'Dome Arena', '2026-04-02 19:30:00', 88.00, false),
    (3, 'The Longwaves', 'Club Atlas', '2026-02-20 21:00:00', 45.00, true);

INSERT INTO Customers (customer_id, name, email, is_active) VALUES
    (10, 'Ada Reyes', 'ada@example.com', true),
    (11, 'Bo Tanaka', 'bo@example.com', true),
    (12, 'Cal Nowak', 'cal@example.com', false);

DELIMITER $$

CREATE PROCEDURE get_customer_tickets(IN p_customer_id INT)
BEGIN
    SELECT t.ticket_id, c.artist, c.venue, c.concert_date, c.ticket_price, t.purchase_date
    FROM Tickets t
    JOIN Concerts c ON c.concert_id = t.concert_id
    WHERE t.customer_id = p_customer_id
      AND t.is_refunded = false
    ORDER BY c.concert_date;
END$$

CREATE PROCEDURE get_concert_customers(IN p_concert_id INT)
BEGIN
    SELECT DISTINCT cu.customer_id, cu.name, cu.email
    FROM Customers cu
    JOIN Tickets t ON t.customer_id = cu.customer_id
    WHERE t.concert_id = p_concert_id
      AND t.is_refunded = false
    ORDER BY cu.name;
END$$

CREATE PROCEDURE record_ticket_purchase(IN p_concert_id INT, IN p_customer_id INT)
BEGIN
    IF NOT EXISTS (SELECT 1 FROM Concerts WHERE concert_id = p_concert_id AND is_cancelled = false) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Concert unavailable';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM Customers WHERE customer_id = p_customer_id AND is_active = true) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Customer not active';
    END IF;
    INSERT INTO Tickets (concert_id, customer_id, purchase_date, is_refunded)
    VALUES (p_concert_id, p_customer_id, NOW(), false);
END$$

CREATE PROCEDURE update_concert_venue(IN p_concert_id INT, IN p_venue VARCHAR(100))
BEGIN
    UPDATE Concerts
    SET venue = p_venue
    WHERE concert_id = p_concert_id
      AND is_cancelled = false;
END$$

CREATE PROCEDURE tickets_sold_per_artist()
BEGIN
    SELECT c.artist, COUNT(t.ticket_id) AS tickets_sold
    FROM Concerts c
    LEFT JOIN Tickets t ON t.concert_id = c.concert_id AND t.is_refunded = false
    WHERE c.is_cancelled = false
    GROUP BY c.artist
    ORDER BY tickets_sold DESC, c.artist;
END$$

DELIMITER ;

CALL record_ticket_purchase(1, 10);
CALL record_ticket_purchase(1, 11);
CALL record_ticket_purchase(2, 10);
CALL update_concert_venue(1, 'Riverside Hall (East Stage)');
CALL get_customer_tickets(10);
CALL get_concert_customers(1);
CALL tickets_sold_per_artist();

