CREATE TABLE Pets (
    pet_id       INT PRIMARY KEY,
    name         VARCHAR(50) NOT NULL,
    species      VARCHAR(30) NOT NULL,
    breed        VARCHAR(50),
    age          INT,
    status       VARCHAR(20) NOT NULL DEFAULT 'available',
    is_available BOOLEAN NOT NULL DEFAULT true
);

CREATE TABLE Adopters (
    adopter_id     INT PRIMARY KEY,
    first_name     VARCHAR(50),
    last_name      VARCHAR(50),
    email          VARCHAR(100) UNIQUE,
    email_verified BOOLEAN NOT NULL DEFAULT false
);

CREATE TABLE Adoptions (
    adoption_id   SERIAL PRIMARY KEY,
    pet_id        INT REFERENCES Pets(pet_id),
    adopter_id    INT REFERENCES Adopters(adopter_id),
    adoption_date DATE NOT NULL,
    is_finalized  BOOLEAN NOT NULL DEFAULT false
);

INSERT INTO Pets (pet_id, name, species, breed, age, status, is_available) VALUES
    (1, 'Rex',   'Dog',  'Beagle',    3, 'available', true),
    (2, 'Luna',  'Cat',  'Siamese',   2, 'available', true),
    (3, 'Buddy', 'Dog',  'Labrador',  5, 'adopted',   false),
    (4, 'Milo',  'Dog',  'Poodle',    1, 'available', true),
    (5, 'Ziggy', 'Bird', 'Cockatiel', 4, 'available', true);

INSERT INTO Adopters (adopter_id, first_name, last_name, email, email_verified) VALUES
    (10, 'Ana',  'Ferreira', 'ana@example.com',  true),
