VALUES (3, 10, DATE '2024-03-11', true);

CREATE OR REPLACE FUNCTION available_pets_by_species(p_species VARCHAR)
RETURNS SETOF Pets AS $$
    SELECT * FROM Pets
    WHERE species = p_species
      AND is_available = true
    ORDER BY age;
$$ LANGUAGE sql;

CREATE OR REPLACE FUNCTION pets_of_adopter(p_adopter_id INT)
RETURNS TABLE (pet_id INT, name VARCHAR, species VARCHAR, adoption_date DATE) AS $$
    SELECT p.pet_id, p.name, p.species, a.adoption_date
    FROM Adoptions a
    JOIN Pets p ON p.pet_id = a.pet_id
    WHERE a.adopter_id = p_adopter_id
      AND a.is_finalized = true
    ORDER BY a.adoption_date DESC;
$$ LANGUAGE sql;

CREATE OR REPLACE FUNCTION mark_adopted(p_pet_id INT) RETURNS VOID AS $$
    UPDATE Pets
    SET status = 'adopted', is_available = false
    WHERE pet_id = p_pet_id;
$$ LANGUAGE sql;

CREATE OR REPLACE FUNCTION record_adoption(p_pet_id INT, p_adopter_id INT, p_date DATE)
RETURNS INT AS $$
DECLARE v_adoption_id INT;
BEGIN
    PERFORM 1 FROM Pets WHERE pet_id = p_pet_id AND is_available = true;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Pet % is not available for adoption', p_pet_id;
    END IF;
    PERFORM 1 FROM Adopters WHERE adopter_id = p_adopter_id AND email_verified = true;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Adopter % has no verified email', p_adopter_id;
    END IF;
    INSERT INTO Adoptions (pet_id, adopter_id, adoption_date, is_finalized)
    VALUES (p_pet_id, p_adopter_id, p_date, true)
    RETURNING adoption_id INTO v_adoption_id;
    PERFORM mark_adopted(p_pet_id);
    RETURN v_adoption_id;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION pets_per_species()
RETURNS TABLE (species VARCHAR, total BIGINT, still_available BIGINT) AS $$
    SELECT p.species,
           COUNT(*),
           COUNT(*) FILTER (WHERE p.is_available = true)
    FROM Pets p
    GROUP BY p.species
    ORDER BY p.species;
$$ LANGUAGE sql;

