CREATE FUNCTION vehicle_services(p_vehicle_id INT)
RETURNS TABLE (service_id INT, service_date DATE, description TEXT, cost DECIMAL, is_paid BOOLEAN) AS $$
    SELECT s.service_id, s.service_date, s.description, s.cost, s.is_paid
    FROM Services s
    WHERE s.vehicle_id = p_vehicle_id
    ORDER BY s.service_date;
$$ LANGUAGE sql;

CREATE FUNCTION vehicles_by_mechanic(p_mechanic_id INT)
RETURNS TABLE (vehicle_id INT, make VARCHAR, model VARCHAR, license_plate VARCHAR) AS $$
    SELECT DISTINCT v.vehicle_id, v.make, v.model, v.license_plate
    FROM Vehicles v
    JOIN Services s ON s.vehicle_id = v.vehicle_id
    WHERE s.mechanic_id = p_mechanic_id
      AND v.in_fleet = true
    ORDER BY v.vehicle_id;
$$ LANGUAGE sql;

CREATE FUNCTION record_service(p_vehicle_id INT, p_mechanic_id INT, p_date DATE,
                               p_description TEXT, p_cost DECIMAL)
RETURNS INT AS $$
DECLARE
    v_new_id INT;
BEGIN
    IF NOT EXISTS (SELECT 1 FROM Vehicles WHERE vehicle_id = p_vehicle_id AND in_fleet = true) THEN
        RAISE EXCEPTION 'vehicle % is not in the active fleet', p_vehicle_id;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM Mechanics WHERE mechanic_id = p_mechanic_id AND on_staff = true) THEN
        RAISE EXCEPTION 'mechanic % is not on staff', p_mechanic_id;
    END IF;
    SELECT COALESCE(MAX(service_id), 0) + 1 INTO v_new_id FROM Services;
    INSERT INTO Services VALUES (v_new_id, p_vehicle_id, p_mechanic_id, p_date,
                                 p_description, p_cost, false);
    RETURN v_new_id;
END;
$$ LANGUAGE plpgsql;

CREATE FUNCTION update_service_cost(p_service_id INT, p_cost DECIMAL)
RETURNS DECIMAL AS $$
DECLARE
    v_cost DECIMAL;
BEGIN
    UPDATE Services
    SET cost = p_cost
    WHERE service_id = p_service_id
      AND is_paid = false
    RETURNING cost INTO v_cost;
    IF v_cost IS NULL THEN
        RAISE EXCEPTION 'service % is missing or already settled', p_service_id;
    END IF;
    RETURN v_cost;
END;
$$ LANGUAGE plpgsql;

CREATE VIEW vehicle_service_totals AS
    SELECT v.vehicle_id, v.license_plate,
           COALESCE(SUM(s.cost), 0) AS total_cost,
           COALESCE(SUM(CASE WHEN s.is_paid = false THEN s.cost ELSE 0 END), 0) AS outstanding
    FROM Vehicles v
    LEFT JOIN Services s ON s.vehicle_id = v.vehicle_id
    GROUP BY v.vehicle_id, v.license_plate
    ORDER BY v.vehicle_id;

