    (100, 1, 10, '2024-03-01 08:00', 2.40, 'KJFK', 'KBOS', TRUE),
    (101, 1, 11, '2024-03-04 13:30', 1.10, 'KBOS', 'KPVD', TRUE),
    (102, 2, 10, '2024-03-07 06:15', 3.75, 'KPVD', 'KJFK', TRUE),
    (103, 3, 10, '2024-03-09 17:00', 0.90, 'KJFK', 'KTEB', FALSE);

CREATE FUNCTION pilot_flights(p_license VARCHAR)
RETURNS TABLE (flight_id INT, flight_date TIMESTAMP, duration_hours DECIMAL, route TEXT) AS $$
    SELECT f.flight_id, f.flight_date, f.duration_hours, f.origin || '-' || f.destination
    FROM Flights f
    JOIN Pilots p ON p.pilot_id = f.pilot_id
    WHERE p.license_number = p_license AND f.logged = TRUE
    ORDER BY f.flight_date;
$$ LANGUAGE sql;

CREATE FUNCTION aircraft_flights(p_registration VARCHAR)
RETURNS TABLE (flight_id INT, pilot_name VARCHAR, flight_date TIMESTAMP, duration_hours DECIMAL) AS $$
    SELECT f.flight_id, p.name, f.flight_date, f.duration_hours
    FROM Flights f
    JOIN Aircraft a ON a.aircraft_id = f.aircraft_id
    JOIN Pilots   p ON p.pilot_id    = f.pilot_id
    WHERE a.registration = p_registration
    ORDER BY f.flight_date;
$$ LANGUAGE sql;

CREATE FUNCTION log_flight(p_flight_id INT, p_license VARCHAR, p_registration VARCHAR,
                           p_date TIMESTAMP, p_hours DECIMAL, p_from VARCHAR, p_to VARCHAR)
RETURNS INT AS $$
    INSERT INTO Flights (flight_id, pilot_id, aircraft_id, flight_date,
                         duration_hours, origin, destination, logged)
    SELECT p_flight_id, p.pilot_id, a.aircraft_id, p_date, p_hours, p_from, p_to, TRUE
    FROM Pilots p, Aircraft a
    WHERE p.license_number = p_license
      AND p.is_active = TRUE
      AND a.registration = p_registration
      AND a.grounded = FALSE
    RETURNING flight_id;
$$ LANGUAGE sql;

CREATE FUNCTION update_destination(p_flight_id INT, p_to VARCHAR)
RETURNS INT AS $$
    UPDATE Flights
    SET destination = p_to
    WHERE flight_id = p_flight_id AND logged = TRUE
    RETURNING flight_id;
$$ LANGUAGE sql;

CREATE FUNCTION pilot_total_hours()
RETURNS TABLE (name VARCHAR, total_hours DECIMAL, active BOOLEAN) AS $$
    SELECT p.name, COALESCE(SUM(f.duration_hours), 0), p.is_active
    FROM Pilots p
    LEFT JOIN Flights f ON f.pilot_id = p.pilot_id AND f.logged = TRUE
    GROUP BY p.name, p.is_active
    ORDER BY 2 DESC;
$$ LANGUAGE sql;

