CREATE TABLE Users (
    user_id INT PRIMARY KEY,
    username VARCHAR(255),
    registration_date DATE
);

CREATE TABLE Pages (
    page_id INT PRIMARY KEY,
    page_url VARCHAR(255),
    page_title VARCHAR(255)
);

CREATE TABLE PageViews (
    view_id INT PRIMARY KEY AUTO_INCREMENT,
    user_id INT,
    page_id INT,
    view_timestamp DATETIME,
    duration_seconds INT,
    is_bot_view BOOLEAN DEFAULT false
);

-- 1. Top 5 most viewed pages in the last 24 hours
SELECT p.page_title, COUNT(pv.page_id) AS view_count
FROM PageViews pv
JOIN Pages p ON pv.page_id = p.page_id
WHERE pv.view_timestamp >= NOW() - INTERVAL 24 HOUR AND pv.is_bot_view = false
GROUP BY p.page_title
ORDER BY view_count DESC
LIMIT 5;

-- 2. List all pages viewed by 'VisitorX' today
SELECT DISTINCT p.page_title
FROM PageViews pv
JOIN Users u ON pv.user_id = u.user_id
JOIN Pages p ON pv.page_id = p.page_id
WHERE u.username = 'VisitorX' AND DATE(pv.view_timestamp) = CURDATE() AND pv.is_bot_view = false;

-- 3. Record a page view for user_id 101 on page_id 201, now, duration 60 seconds
INSERT INTO PageViews (user_id, page_id, view_timestamp, duration_seconds, is_bot_view)
VALUES (101, 201, NOW(), 60, false);

-- 4. Update the duration_seconds for view_id 301 to 90
UPDATE PageViews
SET duration_seconds = 90
