ALTER TABLE Courses     ADD COLUMN is_active BOOLEAN NOT NULL DEFAULT true;
ALTER TABLE Instructors ADD COLUMN is_active BOOLEAN NOT NULL DEFAULT true;
ALTER TABLE Schedules   ADD COLUMN is_cancelled BOOLEAN NOT NULL DEFAULT false;
ALTER TABLE Schedules   ADD COLUMN is_published BOOLEAN NOT NULL DEFAULT false;
ALTER TABLE Schedules   ALTER COLUMN schedule_id ADD GENERATED BY DEFAULT AS IDENTITY;

-- 1. Courses taught by a specific instructor in a given semester.
CREATE OR REPLACE FUNCTION courses_of_instructor(p_instructor_id INT, p_semester VARCHAR, p_year INT)
RETURNS TABLE (course_code VARCHAR, name VARCHAR, day_of_week VARCHAR, start_time TIME) AS $$
    SELECT c.course_code, c.name, s.day_of_week, s.start_time
    FROM Schedules s
    JOIN Courses c ON c.course_id = s.course_id
    WHERE s.instructor_id = p_instructor_id
      AND s.semester = p_semester
      AND s.year = p_year
      AND s.is_cancelled = false
    ORDER BY s.day_of_week, s.start_time;
$$ LANGUAGE sql STABLE;

-- 2. Courses scheduled on Monday mornings (published offerings only).
CREATE OR REPLACE FUNCTION monday_morning_courses(p_semester VARCHAR, p_year INT)
RETURNS TABLE (course_code VARCHAR, name VARCHAR, instructor VARCHAR, start_time TIME) AS $$
    SELECT c.course_code, c.name, i.first_name || ' ' || i.last_name, s.start_time
    FROM Schedules s
    JOIN Courses c ON c.course_id = s.course_id
    JOIN Instructors i ON i.instructor_id = s.instructor_id
    WHERE s.day_of_week = 'Monday'
      AND s.start_time >= TIME '06:00'
      AND s.start_time < TIME '12:00'
      AND s.semester = p_semester
      AND s.year = p_year
      AND s.is_published = true
      AND s.is_cancelled = false
    ORDER BY s.start_time;
$$ LANGUAGE sql STABLE;

-- 3. Number of distinct courses an instructor teaches in a semester.
CREATE OR REPLACE FUNCTION instructor_course_count(p_instructor_id INT, p_semester VARCHAR, p_year INT)
RETURNS BIGINT AS $$
    SELECT COUNT(DISTINCT course_id)
    FROM Schedules
    WHERE instructor_id = p_instructor_id
      AND semester = p_semester
      AND year = p_year
      AND is_cancelled = false;
$$ LANGUAGE sql STABLE;

-- 4. Schedule a new course offering.
CREATE OR REPLACE FUNCTION schedule_offering(p_course_id INT, p_instructor_id INT, p_semester VARCHAR,
                                             p_year INT, p_day VARCHAR, p_start TIME, p_end TIME)
RETURNS INT AS $$
DECLARE v_id INT;
BEGIN
    IF NOT EXISTS (SELECT 1 FROM Courses WHERE course_id = p_course_id AND is_active = true) THEN
        RAISE EXCEPTION 'Course % is not active', p_course_id;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM Instructors WHERE instructor_id = p_instructor_id AND is_active = true) THEN
        RAISE EXCEPTION 'Instructor % is not active', p_instructor_id;
    END IF;
    IF EXISTS (SELECT 1 FROM Schedules
               WHERE instructor_id = p_instructor_id AND semester = p_semester AND year = p_year
                 AND day_of_week = p_day AND is_cancelled = false
                 AND p_start < end_time AND p_end > start_time) THEN
        RAISE EXCEPTION 'Instructor % already booked on % at %', p_instructor_id, p_day, p_start;
    END IF;
    INSERT INTO Schedules (course_id, instructor_id, semester, year, day_of_week,
                           start_time, end_time, is_published)
    VALUES (p_course_id, p_instructor_id, p_semester, p_year, p_day,
            p_start, p_end, true)
    RETURNING schedule_id INTO v_id;
    RETURN v_id;
END;
$$ LANGUAGE plpgsql;

-- 5. Move an existing (live) schedule to another day / start time.
CREATE OR REPLACE FUNCTION reschedule_offering(p_schedule_id INT, p_day VARCHAR, p_start TIME)
RETURNS BOOLEAN AS $$
DECLARE v_rows INT;
BEGIN
    UPDATE Schedules
    SET day_of_week = p_day,
        end_time = p_start + (end_time - start_time),
        start_time = p_start,
        is_published = false
    WHERE schedule_id = p_schedule_id
      AND is_cancelled = false;
    GET DIAGNOSTICS v_rows = ROW_COUNT;
    RETURN v_rows > 0;
END;
$$ LANGUAGE plpgsql;

-- Driver: build one semester's timetable and report on it.
DO $$
DECLARE v_schedule_id INT;
BEGIN
    INSERT INTO Courses (course_id, name, course_code) VALUES
        (101, 'Databases', 'CS310'),
        (102, 'Compilers', 'CS420');
    INSERT INTO Instructors (instructor_id, first_name, last_name, department)
        VALUES (1, 'Ada', 'Byron', 'Computer Science');

    v_schedule_id := schedule_offering(101, 1, 'Fall', 2025, 'Monday', TIME '09:00', TIME '10:30');
    PERFORM schedule_offering(102, 1, 'Fall', 2025, 'Wednesday', TIME '14:00', TIME '15:30');

    IF reschedule_offering(v_schedule_id, 'Monday', TIME '08:00') THEN
        UPDATE Schedules SET is_published = true WHERE schedule_id = v_schedule_id;
    END IF;

    RAISE NOTICE 'Ada teaches % courses in Fall 2025', instructor_course_count(1, 'Fall', 2025);
END;
$$;

SELECT * FROM courses_of_instructor(1, 'Fall', 2025);
SELECT * FROM monday_morning_courses('Fall', 2025);

