-- Grant management module (PostgreSQL)

ALTER TABLE Researchers      ADD COLUMN is_active BOOLEAN NOT NULL DEFAULT true;
ALTER TABLE Grants           ADD COLUMN is_closed BOOLEAN NOT NULL DEFAULT false;
ALTER TABLE GrantAssignments ADD COLUMN is_lead   BOOLEAN NOT NULL DEFAULT false;

-- 1. All grants a specific researcher is involved in
CREATE FUNCTION grants_of_researcher(p_researcher_id INT)
RETURNS TABLE (grant_id INT, title VARCHAR, funding_agency VARCHAR,
               amount DECIMAL, role VARCHAR, is_lead BOOLEAN) AS $$
    SELECT g.grant_id, g.title, g.funding_agency, g.amount, ga.role, ga.is_lead
    FROM GrantAssignments ga
    JOIN Grants g ON g.grant_id = ga.grant_id
    WHERE ga.researcher_id = p_researcher_id
    ORDER BY g.start_date DESC;
$$ LANGUAGE sql STABLE;

-- 2. NIH grants over $100,000
CREATE FUNCTION large_nih_grants()
RETURNS TABLE (grant_id INT, title VARCHAR, amount DECIMAL, end_date DATE,
               is_closed BOOLEAN) AS $$
    SELECT g.grant_id, g.title, g.amount, g.end_date, g.is_closed
    FROM Grants g
    WHERE g.funding_agency = 'NIH'
      AND g.amount > 100000
    ORDER BY g.amount DESC;
$$ LANGUAGE sql STABLE;

-- 3. Headcount per grant, with the number of designated leads
CREATE FUNCTION researchers_per_grant()
RETURNS TABLE (grant_id INT, title VARCHAR, researcher_count BIGINT, lead_count BIGINT) AS $$
    SELECT g.grant_id, g.title,
           count(ga.researcher_id),
           count(ga.researcher_id) FILTER (WHERE ga.is_lead = true)
    FROM Grants g
    LEFT JOIN GrantAssignments ga ON ga.grant_id = g.grant_id
    GROUP BY g.grant_id, g.title
    ORDER BY 3 DESC, g.grant_id;
$$ LANGUAGE sql STABLE;

-- 4. Assign a researcher to a grant; a grant has at most one lead
CREATE FUNCTION assign_researcher(p_researcher_id INT, p_grant_id INT,
                                  p_role VARCHAR, p_is_lead BOOLEAN)
RETURNS INT AS $$
DECLARE v_assignment_id INT;
BEGIN
    IF NOT EXISTS (SELECT 1 FROM Researchers
                   WHERE researcher_id = p_researcher_id AND is_active = true) THEN
        RAISE EXCEPTION 'Researcher % is not active', p_researcher_id;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM Grants
                   WHERE grant_id = p_grant_id AND is_closed = false) THEN
        RAISE EXCEPTION 'Grant % is closed or unknown', p_grant_id;
    END IF;
    IF p_is_lead THEN
        UPDATE GrantAssignments SET is_lead = false
        WHERE grant_id = p_grant_id AND is_lead = true;
    END IF;
    INSERT INTO GrantAssignments (researcher_id, grant_id, role, is_lead)
    VALUES (p_researcher_id, p_grant_id, p_role, p_is_lead)
    RETURNING assignment_id INTO v_assignment_id;
    RETURN v_assignment_id;
END;
$$ LANGUAGE plpgsql;

-- 5. Update the role of a researcher on a grant
CREATE FUNCTION update_assignment_role(p_researcher_id INT, p_grant_id INT,
                                       p_role VARCHAR)
RETURNS BOOLEAN AS $$
DECLARE v_rows INT;
BEGIN
    UPDATE GrantAssignments
    SET role = p_role,
        is_lead = (p_role = 'Principal Investigator')
    WHERE researcher_id = p_researcher_id
      AND grant_id = p_grant_id;
    GET DIAGNOSTICS v_rows = ROW_COUNT;
    IF v_rows = 0 THEN
        RETURN false;
    END IF;
    RETURN true;
END;
$$ LANGUAGE plpgsql;

-- Driver
INSERT INTO Researchers (researcher_id, first_name, last_name, department, is_active)
VALUES (1, 'Ada', 'Nowak', 'Genomics', true),
       (2, 'Bo', 'Lindqvist', 'Genomics', true),
       (3, 'Cy', 'Herrera', 'Biostatistics', false);

INSERT INTO Grants (grant_id, title, funding_agency, amount, start_date, end_date, is_closed)
VALUES (10, 'Single-cell Atlas', 'NIH', 450000, '2024-01-01', '2026-12-31', false),
       (11, 'Legacy Sequencing', 'NIH', 120000, '2018-01-01', '2020-12-31', true),
       (12, 'Methods Workshop', 'NSF', 60000, '2025-03-01', '2026-02-28', false);

SELECT assign_researcher(1, 10, 'Principal Investigator', true);
SELECT assign_researcher(2, 10, 'Co-Investigator', false);
SELECT assign_researcher(2, 12, 'Principal Investigator', true);
SELECT update_assignment_role(2, 10, 'Principal Investigator');

SELECT * FROM grants_of_researcher(2);
SELECT * FROM large_nih_grants();
SELECT * FROM researchers_per_grant();

